$liquid = $service->saveMedicine(['name'=>'Opened-pack fixture','category_id'=>$category,'base_unit'=>'ml','generic_name'=>'Fixture liquid','strength'=>'Fixture concentration','dosage_form'=>'Solution','sell_price'=>1,'units'=>[
    ['name'=>'ml','factor'=>1,'sell_price'=>1,'pharmacy_pack_state'=>'opened'],
