$importRow=['Imported fixture',$db->table('categories')->where('id',$category)->get()->getRow('name'),'Fixture ingredient','1 mg','Chewable tablet','tablet','tablet=1@1;strip-14=14@10;box=140@80','','Fixture maker','','0','10','28','0.2','IMPORT-LOT',date('Y-m-d',strtotime('+60 days'))];
